:root {
  color-scheme: light;
  --paper: #fffdf8;
  --ink: #282b3a;
  --muted: #77798a;
  --line: #e9e4da;
  --violet: #6956c8;
  --violet-dark: #5140ab;
  --mint: #e4f2e9;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 48px 18px;
  display: grid;
  place-items: start center;
  color: var(--ink);
  background-color: #f4efe5;
  background-image: radial-gradient(#d9d0c0 0.8px, transparent 0.8px);
  background-size: 18px 18px;
}

.board {
  width: min(100%, 650px);
  padding: 36px 40px 22px;
  border: 1px solid #ebe6dc;
  border-radius: 22px;
  background: var(--paper);
  box-shadow: 0 18px 55px #4d46331b, 0 3px 8px #4d46330b;
}
.header { display: flex; align-items: center; gap: 15px; margin-bottom: 28px; }
.mark { display: grid; width: 50px; height: 50px; place-items: center; border-radius: 15px; color: white; background: var(--violet); font-size: 28px; }
.eyebrow { margin: 0 0 3px; color: var(--muted); font-size: 12px; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 0; font-size: 29px; line-height: 1.2; letter-spacing: -.04em; }
h2 { margin: 0; font-size: 17px; font-weight: 720; }
.note-form { display: grid; gap: 9px; }
.note-form label { margin-top: 2px; font-size: 14px; font-weight: 700; }
.hint { color: var(--muted); font-weight: 450; }
textarea, input {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
  color: var(--ink);
  background: #fffefa;
  font: inherit;
  transition: border-color .15s, box-shadow .15s;
}
textarea { min-height: 88px; padding: 12px 14px; resize: vertical; }
input { height: 46px; padding: 0 14px; }
textarea::placeholder, input::placeholder { color: #a2a1a5; }
textarea:focus, input:focus { border-color: var(--violet); box-shadow: 0 0 0 3px #6956c822; }
.add-button {
  justify-self: start;
  min-height: 46px;
  margin-top: 5px;
  padding: 0 18px;
  border: 0;
  border-radius: 10px;
  color: white;
  background: var(--violet);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s, transform .12s, box-shadow .15s;
}
.add-button span { margin-right: 5px; font-size: 20px; vertical-align: -1px; }
.add-button:hover { background: var(--violet-dark); box-shadow: 0 5px 12px #5140ab33; }
.add-button:active { transform: translateY(1px) scale(.98); }
button:focus-visible { outline: 3px solid #a99bea; outline-offset: 3px; }
.tag-section, .notes-section { margin-top: 29px; }
.section-heading { display: flex; min-height: 28px; align-items: center; justify-content: space-between; gap: 12px; }
.section-note { color: var(--muted); font-size: 13px; }
.tag-list { display: flex; flex-wrap: wrap; gap: 8px; min-height: 32px; margin-top: 11px; }
.tag-chip {
  display: inline-flex;
  min-height: 32px;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border: 1px solid #d7e9dc;
  border-radius: 999px;
  color: #365a43;
  background: var(--mint);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
  transition: background .15s, border-color .15s, transform .12s;
}
.tag-chip:hover { border-color: #9fc8aa; background: #d5ebdc; }
.tag-chip:active { transform: scale(.97); }
.tag-chip[aria-pressed="true"] { border-color: var(--violet); color: white; background: var(--violet); }
.tag-count { color: #637568; font-size: 12px; font-weight: 750; }
.tag-chip[aria-pressed="true"] .tag-count { color: #e7e2ff; }
.count { display: inline-grid; min-width: 25px; height: 25px; margin-left: 4px; place-items: center; border-radius: 99px; color: var(--violet); background: #eeeafd; font-size: 13px; vertical-align: 1px; }
.filter-status { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; }
.filter-status strong { color: var(--violet-dark); }
.clear-button { padding: 4px 8px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); background: white; font: inherit; cursor: pointer; }
.clear-button:hover { border-color: #c9c1e8; background: #f5f2ff; }
.notes-list { display: grid; gap: 10px; margin-top: 10px; }
.note-card { padding: 15px 16px 13px; border: 1px solid var(--line); border-radius: 12px; background: #fffefa; box-shadow: 0 2px 5px #4d463308; }
.note-text { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.55; }
.note-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 11px; }
.note-tag { padding: 3px 8px; border-radius: 999px; color: #536a59; background: var(--mint); font-size: 12px; }
.empty-state { margin: 15px 0 4px; padding: 18px; border: 1px dashed #ded8ce; border-radius: 11px; color: var(--muted); text-align: center; font-size: 14px; }
footer { margin-top: 28px; padding-top: 15px; border-top: 1px solid #f0ece4; color: #9995a0; text-align: center; font-size: 12px; }
footer span { color: var(--violet); }

@media (max-width: 520px) {
  body { padding: 18px 12px; }
  .board { padding: 26px 20px 18px; border-radius: 17px; }
  .header { margin-bottom: 23px; }
  h1 { font-size: 26px; }
  .section-heading { align-items: flex-start; }
}

const form = document.querySelector('#note-form');
const textInput = document.querySelector('#note-text');
const tagsInput = document.querySelector('#note-tags');
const notesList = document.querySelector('#notes-list');
const tagList = document.querySelector('#tag-list');
const emptyState = document.querySelector('#empty-state');
const noteCount = document.querySelector('#note-count');
const filterStatus = document.querySelector('#filter-status');
const activeFilter = document.querySelector('#active-filter');
const clearFilter = document.querySelector('#clear-filter');

const notes = [];
let selectedTag = null;

function normalizeTags(value) {
  const seen = new Set();
  return value.split(',').map(tag => tag.trim()).filter(tag => {
    const key = tag.toLocaleLowerCase();
    if (!tag || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function render() {
  const counts = new Map();
  for (const note of notes) {
    for (const tag of note.tags) {
      const key = tag.toLocaleLowerCase();
      const current = counts.get(key);
      counts.set(key, { label: current?.label ?? tag, count: (current?.count ?? 0) + 1 });
    }
  }

  tagList.replaceChildren();
  for (const [key, item] of counts) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tag-chip';
    button.setAttribute('aria-pressed', String(selectedTag === key));
    button.setAttribute('aria-label', `${item.label}, ${item.count} ${item.count === 1 ? 'note' : 'notes'}`);
    const label = document.createElement('span');
    label.textContent = item.label;
    const count = document.createElement('span');
    count.className = 'tag-count';
    count.textContent = item.count;
    button.append(label, count);
    button.addEventListener('click', () => {
      selectedTag = selectedTag === key ? null : key;
      render();
    });
    tagList.append(button);
  }

  const visibleNotes = notes.filter(note => !selectedTag || note.tags.some(tag => tag.toLocaleLowerCase() === selectedTag));
  notesList.replaceChildren();
  for (const note of visibleNotes) {
    const card = document.createElement('article');
    card.className = 'note-card';
    const content = document.createElement('p');
    content.className = 'note-text';
    content.textContent = note.text;
    card.append(content);
    if (note.tags.length) {
      const tags = document.createElement('div');
      tags.className = 'note-tags';
      for (const tag of note.tags) {
        const pill = document.createElement('span');
        pill.className = 'note-tag';
        pill.textContent = tag;
        tags.append(pill);
      }
      card.append(tags);
    }
    notesList.append(card);
  }

  noteCount.textContent = visibleNotes.length;
  emptyState.hidden = visibleNotes.length !== 0;
  emptyState.textContent = selectedTag
    ? `No notes tagged “${counts.get(selectedTag)?.label ?? selectedTag}”.`
    : 'Your page is still blank. Add a note to get started.';
  filterStatus.hidden = !selectedTag;
  activeFilter.textContent = counts.get(selectedTag)?.label ?? selectedTag ?? '';
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = textInput.value.trim();
  if (!text) {
    textInput.focus();
    return;
  }
  notes.unshift({ text, tags: normalizeTags(tagsInput.value) });
  form.reset();
  selectedTag = null;
  render();
  textInput.focus();
});

clearFilter.addEventListener('click', () => {
  selectedTag = null;
  render();
});

render();
